use std::io::Write;
use std::process::ExitCode;

const SHADER: &str = r#"
struct Params { width: u32, height: u32 }
@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> p: Params;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.width || id.y >= p.height) { return; }
    let x = id.x;
    let y = id.y;
    let l = max(x, 1u) - 1u;
    let r = min(x + 1u, p.width - 1u);
    let u = max(y, 1u) - 1u;
    let d = min(y + 1u, p.height - 1u);
    let w = p.width;
    let s = 4u * src[y * w + x] + src[y * w + l] + src[y * w + r]
          + src[u * w + x] + src[d * w + x];
    dst[y * w + x] = s / 8u;
}
"#;

fn parse(path: &str) -> Result<(usize, usize, usize, Vec<u32>), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("read {path}: {e}"))?;
    let mut it = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        it.next()
            .ok_or_else(|| format!("missing {what}"))?
            .parse::<u64>()
            .map_err(|e| format!("bad {what}: {e}"))
    };
    let w = next("width")? as usize;
    let h = next("height")? as usize;
    let steps = next("steps")? as usize;
    if w == 0 || h == 0 || w > 512 || h > 512 {
        return Err("grid size out of range".into());
    }
    let mut cells = Vec::with_capacity(w * h);
    for _ in 0..w * h {
        cells.push(next("cell")? as u32);
    }
    Ok((w, h, steps, cells))
}

fn run_gpu(w: usize, h: usize, steps: usize, cells: &[u32]) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("device: {e}"))?;

    let bytes = (w * h * 4) as u64;
    let usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let mk = |label| {
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some(label),
            size: bytes,
            usage,
            mapped_at_creation: false,
        })
    };
    let bufs = [mk("a"), mk("b")];
    queue.write_buffer(&bufs[0], 0, bytemuck::cast_slice(cells));
    let params = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("params"),
        size: 8,
        usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    queue.write_buffer(&params, 0, bytemuck::cast_slice(&[w as u32, h as u32]));
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: bytes,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: None,
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry { binding: 0, resource: bufs[i].as_entire_binding() },
                    wgpu::BindGroupEntry { binding: 1, resource: bufs[1 - i].as_entire_binding() },
                    wgpu::BindGroupEntry { binding: 2, resource: params.as_entire_binding() },
                ],
            })
        })
        .collect();

    let mut enc = device.create_command_encoder(&Default::default());
    {
        let mut pass = enc.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        for s in 0..steps {
            pass.set_bind_group(0, &groups[s % 2], &[]);
            pass.dispatch_workgroups(w.div_ceil(16) as u32, h.div_ceil(16) as u32, 1);
        }
    }
    enc.copy_buffer_to_buffer(&bufs[steps % 2], 0, &readback, 0, bytes);
    queue.submit([enc.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll: {e}"))?;
    rx.recv().map_err(|e| e.to_string())?.map_err(|e| format!("map: {e}"))?;
    let data = slice.get_mapped_range();
    let out: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: heat <input-file>");
        return ExitCode::FAILURE;
    };
    let result = parse(&path).and_then(|(w, h, steps, cells)| {
        let out = run_gpu(w, h, steps, &cells)?;
        Ok((w, out))
    });
    match result {
        Ok((w, out)) => {
            let mut s = String::with_capacity(out.len() * 8);
            for row in out.chunks(w) {
                let line: Vec<String> = row.iter().map(u32::to_string).collect();
                s.push_str(&line.join(" "));
                s.push('\n');
            }
            let sum: u64 = out.iter().map(|&v| u64::from(v)).sum();
            s.push_str(&format!("SUM {sum}\n"));
            let mut so = std::io::stdout().lock();
            if so.write_all(s.as_bytes()).and_then(|_| so.flush()).is_err() {
                return ExitCode::FAILURE;
            }
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
